INSERT INTO rules (rule_id, section_code, rule_text, rule_type, trigger_text, condition_text, validation_text, action_text, exception_text, output_text) VALUES ('CH2-SEC2_29-R001', '2.29', '2.29 A Any firm/ company coming under the NCLT proceedings shall make a
