INSERT INTO workflows (section_code, step_index, step_text) VALUES ('2.52', 1, 'Evaluate condition: 2.52 Recognition as Pre-shipment Inspection Agency (PSIA) and issuance
of Pre- shipment Certificate (PSIC)
(a) Applications for recognition in respect of PSIAs have to be made online on
DGFT Website (https://dgft.gov.in) by payment of applicable fee in terms of
Appendix 2K of FTP.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('2.52', 2, 'Evaluate condition: (c) The recognized PSIAs will be notified under Appendix 2G for a period of
three years.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('2.52', 3, 'Evaluate condition: (e) A PSIA can also carry out inspections in countries, where it does not have
a full-time equipped branch office but which falls within its area of
operation, by deputing its Inspectors.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('2.52', 4, '2.52 Recognition as Pre-shipment Inspection Agency (PSIA) and issuance
of Pre- shipment Certificate (PSIC)
(a) Applications for recognition in respect of PSIAs have to be made online on
DGFT Website (https://dgft.gov.in) by payment of applicable fee in terms of
Appendix 2K of FTP.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('2.52', 5, '(d) PSIA shall issue PSIC in the format given in Appendix 2H.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('2.52', 6, 'However, for such inspections in
other countries, the PSIA will be required to give prior intimation to
DGFT by sending an email (at psia-travel-dgft@gov.in) and furnishing
details of visit / inspection done by the Inspector in PSIC.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('2.52', 7, '(f) The PSIA applicant(s) may submit online application(s) initially without
bank guarantee, as required under S.No.9 of ANF-2L.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('2.52', 8, 'Their applications
would not be rejected only on the ground of non-submission of bank
guarantee.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('2.52', 9, 'Applicants would, however, be required to submit bank
guarantee or an equivalent financial instrument, before they are notified
as PSIA, by the competent authority.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('2.52', 10, 'Run validation: (d) PSIA shall issue PSIC in the format given in Appendix 2H.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('2.52', 11, 'Run validation: PSIA shall
generate PSICs using the facility provided on the DGFT website.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('2.52', 12, 'Run validation: However, for such inspections in
other countries, the PSIA will be required to give prior intimation to
DGFT by sending an email (at psia-travel-dgft@gov.in) and furnishing
details of visit / inspection done by the Inspector in PSIC.');
INSERT INTO workflows (section_code, step_index, step_text) VALUES ('2.52', 13, 'Handle exception: (e) A PSIA can also carry out inspections in countries, where it does not have
a full-time equipped branch office but which falls within its area of
operation, by deputing its Inspectors.');
