INSERT INTO sections (source_document, chapter_number, chapter_title, section_code, title, purpose, purpose_thanglish, summary, business_meaning, business_explanation, business_explanation_thanglish, raw_text, pages, keywords, intent, tags) VALUES ('HBP Chapter 2.pdf', '2', 'General Provisions Regarding Imports and Exports', '2.90', 'Certificates of Origin (Co O)', '2.90 Certificates of Origin (Co O)
(a) Certificate of Origin (Co O) is an instrument to establish evidence on origin of
goods imported into any country.', 'Indha Certificates of Origin (Co O) section-la, 2.90 Certificates of Origin (Co O)
(a) Certificate of Origin (Co O) is an instrument to establish evidence on origin of
